/* @lc app=leetcode id=3508 lang=kotlin */ class Router(val ml: Int, val q: java.util.ArrayDeque<IntArray> = java.util.ArrayDeque(), val seen: HashSet<Triple<Int, Int, Int>> = HashSet(), val ts: HashMap<Int, ArrayList<Int>> = HashMap(), val hd: HashMap<Int, Int> = HashMap()) { fun addPacket(source: Int, destination: Int, timestamp: Int): Boolean = seen.add(Triple(source, destination, timestamp)).also { ok -> if (ok) (if (q.size >= ml) forwardPacket() else IntArray(0)).let { q.add(intArrayOf(source, destination, timestamp)).also { ts.getOrPut(destination) { ArrayList() }.add(timestamp) } } } fun forwardPacket(): IntArray = q.pollFirst()?.also { p -> seen.remove(Triple(p[0], p[1], p[2])) }?.also { p -> hd.merge(p[1], 1) { a, b -> a + b } } ?: IntArray(0) fun lb(l: List<Int>, h: Int, v: Int): Int = generateSequence(h to l.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (l[m] < v) m + 1 to hi else lo to m } }.last().first fun getCount(destination: Int, startTime: Int, endTime: Int): Int = ts[destination]?.let { l -> (hd[destination] ?: 0).let { h -> lb(l, h, endTime + 1) - lb(l, h, startTime) } } ?: 0 }